"] = 3304060	tSepBackToSchool_Reward[3304060][6][1]["RewardEffect"] = {}	tSepBackToSchool_Reward[3304060][6][1]["RewardEffect"]["Effect"] = tSepBackToSchool_Data["Effect"]	tSepBackToSchool_Reward[3304060][6][1]["LogId"] = 10002424	tSepBackToSchool_Reward[3304060][6][1]["EmoneyLog"] = "350	20671	0	0	1	"	-- 至尊神羚【羊年绝版】	200524	1	赠，1%神佑	30天时效	tSepBackToSchool_Reward[3304060][6][2] = {}	tSepBackToSchool_Reward[3304060][6][2]["EventType"] = tSepBackToSchool_Data["Stc"]["VIPPack"]["EventType"]	tSepBackToSchool_Reward[3304060][6][2]["DataType"] = tSepBackToSchool_Data["Stc"]["VIPPack"]["DataType"]	tSepBackToSchool_Reward[3304060][6][2]["RewardData"] = 1	tSepBackToSchool_Reward[3304060][6][2]["RewardTotalData"] = 1	tSepBackToSchool_Reward[3304060][6][2]["RewardItem"] = {}	tSepBackToSchool_Reward[3304060][6][2]["RewardItem"][1] = {}	tSepBackToSchool_Reward[3304060][6][2]["RewardItem"][1]["Id"] = 200524	tSepBackToSchool_Reward[3304060][6][2]["RewardItem"][1]["Attr"] = "0 1 3 43200 1 0 0 1"	tSepBackToSchool_Reward[3304060][6][2]["DeleteItem"] = {}	tSepBackToSchool_Reward[3304060][6][2]["DeleteItem"][1] = {}	tSepBackToSchool_Reward[3304060][6][2]["DeleteItem"][1]["Id"] = 3304060	tSepBackToSchool_Reward[3304060][6][2]["RewardEffect"] = {}	tSepBackToSchool_Reward[3304060][6][2]["RewardEffect"]["Effect"] = tSepBackToSchool_Data["Effect"]	tSepBackToSchool_Reward[3304060][6][2]["LogId"] = 10002424	tSepBackToSchool_Reward[3304060][6][2]["EmoneyLog"] = "350	20671	0	0	1	"		-- 3304062 500点修行值礼包	tSepBackToSchool_Reward[3304062] = {}	tSepBackToSchool_Reward[3304062]["RewardCultivation"] = {}	tSepBackToSchool_Reward[3304062]["RewardCultivation"]["Value"] = 500	tSepBackToSchool_Reward[3304062]["DeleteItem"] = {}	tSepBackToSchool_Reward[3304062]["DeleteItem"][1] = {}	tSepBackToSchool_Reward[3304062]["DeleteItem"][1]["Id"] = 3304062	tSepBackToSchool_Reward[3304062]["RewardEffect"] = {}	tSepBackToSchool_Reward[3304062]["RewardEffect"]["Effect"] = tSepBackToSchool_Data["Effect"]	tSepBackToSchool_Reward[3304062]["LogId"] = 10002424--------------------------------------逻辑部分--------------------------------------------- 上线触发function SepBackToSchool_GetPacks()	-- 判断时间	if not Sys_ChkFullTime(tSepBackToSchool_Data["AwardTime"]) then		return	end		-- 判断掩码	local nEventType = tSepBackToSchool_Data["Stc"]["Login"]["EventType"]	local nDataType = tSepBackToSchool_Data["Stc"]["Login"]["DataType"]	local nComplete = tSepBackToSchool_Data["Stc"]["Login"]["Complete"]	if Task_ChkStcValue(nEventType,nDataType,">=",nComplete) then		return	end		-- 判断背包	local nSpace = RewardTemplate_GetRewardSpace(tSepBackToSchool_Reward["Login"])	if not User_CheckLeftSpace(nSpace) then		User_TalkChannel2005(tSepBackToSchool_Text["LoginSpace"])		return	end		Task_SetStatistic(nEventType,nDataType,nComplete,1)	RewardTemplate_UseItemAndMsg(tSepBackToSchool_Reward["Login"])end-- 普通礼包function SepBackToSchool_EmoneyMonoPack(nItemId)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断等级	if not User_JudgeLevelAndMetempsychosis(tSepBackToSchool_Data["Level"],tSepBackToSchool_Data["Metempsychosis"][1]) then		Sys_MsgBox(tSepBackToSchool_Text[nItemId]["LevelLimit"] )		return	end		-- 判断赠点上限	local nIndex = 1	local nUserId = Get_UserId()	local nEmoney = Get_UserMonoEMoney(nUserId)	local nAddEmoney = tSepBackToSchool_Reward[nItemId][nIndex]["RewardEMoneyMono"]["Value"]	if nEmoney + nAddEmoney > G_User_MaxEmoneyMono then		Sys_MsgBox(tSepBackToSchool_Text["EMoneyMono"])		return	end		-- 判断掩码	local nEventType = tSepBackToSchool_Data["Stc"]["EmoneyMonoPack"]["EventType"]	local nDataType = tSepBackToSchool_Data["Stc"]["EmoneyMonoPack"]["DataType"]	local nComplete = tSepBackToSchool_Data["Stc"]["EmoneyMonoPack"]["Complete"]	local nData = Get_UserStatisticValue(nEventType,nDataType)	local nTotalData = (nData - nData%10000)/10000	if nTotalData == (nComplete-1) then		nIndex = 2		RewardTemplate_UseItemAndMsg(tSepBackToSchool_Reward[nItemId][nIndex])		return	elseif nTotalData >= nComplete then		Item_DelItem(nItemId)		return	end		-- 给奖	RewardTemplate_UseItemAndMsg(tSepBackToSchool_Reward[nItemId][nIndex])end-- 3304059 纵马江湖礼包function SepBackToSchool_GradientPack(nItemId)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tSepBackToSchool_Data["GradientPackTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tSepBackToSchool_Text[nItemId]["Overdue"])		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteGradientPackOverdue"])		return	end	-- 前	if CommonFunc_GetBeforeActivityTime(tSepBackToSchool_Data["GradientPackTime"]) then		Sys_MsgBox(tSepBackToSchool_Text[nItemId]["Before"])		return	end		-- 判断等级	if not User_JudgeLevelAndMetempsychosis(tSepBackToSchool_Data["Level"],tSepBackToSchool_Data["Metempsychosis"][1]) then		User_TalkChannel2005(tSepBackToSchool_Text[nItemId]["LevelLimit"])		return	end	local nIndex = 1	local nUserId = Get_UserId()	local nUserMetempsychosis = Get_UserMetempsychosis(nUserId)	if nUserMetempsychosis >= tSepBackToSchool_Data["Metempsychosis"][2] then		nIndex = 2	end		-- 判断掩码	local nEventType = tSepBackToSchool_Data["Stc"]["GradientPack"]["EventType"]	local nDataType = tSepBackToSchool_Data["Stc"]["GradientPack"]["DataType"]	local nSingleData = tSepBackToSchool_Data["Stc"]["GradientPack"]["RewardData"]	local nTotalData = tSepBackToSchool_Data["Stc"]["GradientPack"]["RewardTotalData"]	local nData = Get_UserStatisticValue(nEventType,nDataType)	-- 对掩码值进行分解，取出总的次数跟今天的次数	local nNowSingleData = nData%10000	local nNowTotalData = (nData - nNowSingleData)/10000	if Task_StcInterval(nEventType,nDataType,1,4) then		nNowSingleData = 0		nData = nNowTotalData*10000 + nNowSingleData		Task_SetStatistic(nEventType,nDataType,nData,1)		Task_SetStcTimestamp(nEventType,nDataType,0)	end	-- 礼包可最多打开10次	if nNowTotalData >= nTotalData then		Item_DelItem(nItemId)		User_TalkChannel2005(tSepBackToSchool_Text[nItemId]["Ten"])		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteGradientPackWithAward"])		return	end	-- 每天有且仅能打开1次	if nNowSingleData >= nSingleData then		Sys_MsgBox(tSepBackToSchool_Text[nItemId]["HaveReceive"])		return	end		-- 判断背包 第10次比前9次少1个背包空间	local nSpace = RewardTemplate_GetRandomSpace(tSepBackToSchool_Reward[nItemId],nIndex)	if nNowTotalData >= (nTotalData-1) then		nSpace = nSpace - 1	end	local sMsg = string.format(tSepBackToSchool_Text[nItemId]["NoSpace"],nSpace)	if not User_CheckLeftSpace(nSpace) then		Sys_MsgBox(sMsg)		return	end		-- 给奖	nNowSingleData = nNowSingleData + 1	nNowTotalData = nNowTotalData + 1	local nNewData = nNowTotalData*10000 + nNowSingleData	local sStr = ""	if nNowTotalData >= nTotalData then		Item_DelItem(nItemId)		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteGradientPackWithAward"])		sStr = tSepBackToSchool_Text[nItemId]["Ten"]	else		sStr = string.format(tSepBackToSchool_Text[nItemId]["NotTen"],nNowTotalData)	end	Task_SetStatistic(nEventType,nDataType,nNewData,1)	Task_SetStcTimestamp(nEventType,nDataType,0)	User_TalkChannel2005(sStr)	RewardTemplate_NewRandom(tSepBackToSchool_Reward[nItemId],nIndex)	Sys_SaveEmoneyBuy(tSepBackToSchool_Data["EmoneyLog"][nItemId])	User_EffectAdd("self",tSepBackToSchool_Data["Effect"])end-- 3304060 VIP尊享外套包function SepBackToSchool_VIPPackLow(nItemId)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断时间	-- 前	if CommonFunc_GetBeforeActivityTime(tSepBackToSchool_Data["VIPPackTime"]) then		return	end	-- 后	if CommonFunc_GetAfterActivityTime(tSepBackToSchool_Data["VIPPackTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tSepBackToSchool_Text[nItemId]["Overdue"])		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteVIPPackOverdue"])		return	end		-- 判断掩码	local nEventType = tSepBackToSchool_Data["Stc"]["VIPPack"]["EventType"] 	local nDataType = tSepBackToSchool_Data["Stc"]["VIPPack"]["DataType"]	if Task_ChkStcValue(nEventType,nDataType,">",0) then		Item_DelItem(nItemId)		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteVIPPackHaveReceived"])		return	end		-- 判断VIP等级	local nVip = Get_UserVip()	if nVip <= 0 then		Sys_MsgBox(tSepBackToSchool_Text[nItemId]["NotVIP"])		return	end		if nVip <= 3 then		RewardTemplate_UseItemAndMsg(tSepBackToSchool_Reward[nItemId][nVip])	else		LinkItemGossipFunc_New(nItemId,tSepBackToSchool_Data["Dialog"][nVip])	endendfunction SepBackToSchool_VIPPackHigh(nItemId,nVip,nIndex)	-- 判断物品	if not Item_ChkItem(nItemId) then		return	end		-- 判断时间	if CommonFunc_GetAfterActivityTime(tSepBackToSchool_Data["VIPPackTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tSepBackToSchool_Text[nItemId]["Overdue"])		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteVIPPackOverdue"])		return	end		-- 判断掩码	local nEventType = tSepBackToSchool_Data["Stc"]["VIPPack"]["EventType"] 	local nDataType = tSepBackToSchool_Data["Stc"]["VIPPack"]["DataType"]	if Task_ChkStcValue(nEventType,nDataType,">",0) then		Item_DelItem(nItemId)		Sys_SaveActionFestivalLog(tSepBackToSchool_Data["Log"]["DeleteVIPPackHaveReceived"])		return	end		-- 判断VIP等级	local nUserVip = Get_UserVip()	if nUserVip <= 0 then		Sys_MsgBox(tSepBackToSchool_Text[nItemId]["NotVIP"])		return	end	if nUserVip ~= nVip then		LinkItemGossipFunc_New(nItemId,"1-1")		return	end		RewardTemplate_UseItemAndMsg(tSepBackToSchool_Reward[nItemId][nVip][nIndex])end--------------------------------------物品配置--------------------------------------------- 3304058 天石(赠)福利月卡tItem[3304058] = tItem[3304058] or {}tItem[3304058]["Function"] = function(nItemId,sItemName)	SepBackToSchool_EmoneyMonoPack(nItemId)end-- 3304059 纵马江湖礼包-- 头像tItemFace[3304059] = 746tItem[3304059] = tItem[3304059] or {}tItem[3304059]["DialogueText"] = tSepBackToSchool_Text[3304059]tItem[3304059]["Function"] = function(nItemId,s